import { SignupTrend } from './SignupTrend';

export function App() {
  return (
    <main className="container section stack">
      <h1>Sign-up trends</h1>
      <SignupTrend />
    </main>
  );
}

import { useState, type KeyboardEvent, type PointerEvent } from 'react';
import { CHANNELS, DATA } from './signups';

const W = 720;
const H = 320;
const M = { t: 16, r: 120, b: 32, l: 44 };
const PW = W - M.l - M.r;
const PH = H - M.t - M.b;
const YMAX = 400;
const TICKS = [0, 100, 200, 300, 400];

const x = (i: number) => M.l + (i / (DATA.length - 1)) * PW;
const y = (v: number) => M.t + PH - (v / YMAX) * PH;
const fmt = (iso: string) =>
  new Date(iso + 'T00:00:00Z').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });

export function SignupTrend() {
  const [view, setView] = useState<'chart' | 'table'>('chart');
  const [hover, setHover] = useState<number | null>(null);

  const onMove = (e: PointerEvent<SVGSVGElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    const px = ((e.clientX - r.left) / r.width) * W;
    const i = Math.round(((px - M.l) / PW) * (DATA.length - 1));
    setHover(Math.max(0, Math.min(DATA.length - 1, i)));
  };
  const onKey = (e: KeyboardEvent) => {
    if (e.key === 'ArrowRight') setHover((h) => Math.min(DATA.length - 1, (h ?? -1) + 1));
    else if (e.key === 'ArrowLeft') setHover((h) => Math.max(0, (h ?? DATA.length) - 1));
    else if (e.key === 'Escape') setHover(null);
    else return;
    e.preventDefault();
  };

  const row = hover === null ? null : DATA[hover];
  const first = DATA[0];
  const last = DATA[DATA.length - 1];

  return (
    <section className="panel">
      <div className="panel-header">
        <div className="stack">
          <h2 className="panel-title">Weekly sign-ups by channel</h2>
          <p className="muted">
            {fmt(first.week)} – {fmt(last.week)} 2026, 26 weeks, weeks starting Monday
          </p>
        </div>
        <div className="segmented" role="radiogroup" aria-label="View">
          {(['chart', 'table'] as const).map((v) => (
            <button
              key={v}
              type="button"
              role="radio"
              aria-checked={view === v}
              className="segmented-item"
              onClick={() => setView(v)}
            >
              {v === 'chart' ? 'Chart' : 'Table'}
            </button>
          ))}
        </div>
      </div>

      <div className="panel-body stack">
        <div className="row" style={{ flexWrap: 'wrap', gap: 'var(--space-6)' }}>
          {CHANNELS.map((c) => {
            const a = first.values[c.key];
            const b = last.values[c.key];
            const pct = Math.round(((b - a) / a) * 100);
            return (
              <div className="stat" key={c.key}>
                <span className="stat-label">
                  <svg width="16" height="8" aria-hidden="true" style={{ marginInlineEnd: 'var(--space-2)' }}>
                    <line x1="0" x2="16" y1="4" y2="4" stroke={c.series} strokeWidth="2" strokeLinecap="round" />
                  </svg>
                  {c.label}
                </span>
                <span className="stat-value num">{b}</span>
                <span className="stat-note">
                  this week, {pct >= 0 ? '+' : '−'}
                  {Math.abs(pct)}% vs 26 weeks ago
                </span>
              </div>
            );
          })}
        </div>

        {view === 'chart' ? (
          <figure className="chart" style={{ position: 'relative', margin: 0 }}>
            <svg
              className="chart-plot"
              viewBox={`0 0 ${W} ${H}`}
              width="100%"
              role="img"
              aria-label="Line chart of weekly sign-ups for Organic search, Paid and Referral over 26 weeks. Switch to Table for exact values."
              tabIndex={0}
              onPointerMove={onMove}
              onPointerLeave={() => setHover(null)}
              onKeyDown={onKey}
              onBlur={() => setHover(null)}
            >
              {TICKS.map((t) => (
                <g key={t}>
                  <line
                    className="chart-grid"
                    x1={M.l}
                    x2={M.l + PW}
                    y1={y(t)}
                    y2={y(t)}
                    stroke="var(--color-divider)"
                  />
                  <text
                    className="chart-axis"
                    x={M.l - 8}
                    y={y(t)}
                    textAnchor="end"
                    dominantBaseline="middle"
                    fill="var(--color-neutral-600)"
                    fontSize="12"
                  >
                    {t}
                  </text>
                </g>
              ))}
              {DATA.map((d, i) =>
                i % 5 === 0 || i === DATA.length - 1 ? (
                  <text
                    key={d.week}
                    className="chart-axis"
                    x={x(i)}
                    y={H - 10}
                    textAnchor="middle"
                    fill="var(--color-neutral-600)"
                    fontSize="12"
                  >
                    {fmt(d.week)}
                  </text>
                ) : null,
              )}

              {CHANNELS.map((c) => (
                <g key={c.key}>
                  <polyline
                    className="chart-line"
                    fill="none"
                    stroke={c.series}
                    strokeWidth="2"
                    strokeLinejoin="round"
                    strokeLinecap="round"
                    points={DATA.map((d, i) => `${x(i)},${y(d.values[c.key])}`).join(' ')}
                  />
                  <text
                    x={x(DATA.length - 1) + 10}
                    y={y(last.values[c.key])}
                    dominantBaseline="middle"
                    fill="var(--color-text)"
                    fontSize="12"
                  >
                    {c.label}
                  </text>
                </g>
              ))}

              {hover !== null && row && (
                <g pointerEvents="none">
                  <line x1={x(hover)} x2={x(hover)} y1={M.t} y2={M.t + PH} stroke="var(--color-neutral-600)" />
                  {CHANNELS.map((c) => (
                    <circle
                      key={c.key}
                      cx={x(hover)}
                      cy={y(row.values[c.key])}
                      r="4"
                      fill={c.series}
                      stroke="var(--color-surface)"
                      strokeWidth="2"
                    />
                  ))}
                </g>
              )}
            </svg>

            {hover !== null && row && (
              <div
                className="chart-tooltip"
                role="status"
                style={{
                  position: 'absolute',
                  top: 'var(--space-2)',
                  insetInlineStart: `${(x(hover) / W) * 100}%`,
                  transform: hover > DATA.length / 2 ? 'translateX(calc(-100% - 12px))' : 'translateX(12px)',
                  pointerEvents: 'none',
                }}
              >
                <div className="label">Week of {fmt(row.week)}</div>
                {CHANNELS.map((c) => (
                  <div key={c.key} className="row" style={{ justifyContent: 'space-between', gap: 'var(--space-4)' }}>
                    <span>
                      <svg width="8" height="8" aria-hidden="true" style={{ marginInlineEnd: 'var(--space-2)' }}>
                        <circle cx="4" cy="4" r="4" fill={c.series} />
                      </svg>
                      {c.label}
                    </span>
                    <span className="num">{row.values[c.key]}</span>
                  </div>
                ))}
              </div>
            )}
            <figcaption className="muted">Sign-ups per week. Hover, or focus the chart and use ← → to read a week.</figcaption>
          </figure>
        ) : (
          <div className="table-wrap">
            <table className="table table-compact table-sticky">
              <thead>
                <tr>
                  <th scope="col">Week of</th>
                  {CHANNELS.map((c) => (
                    <th scope="col" key={c.key} className="num">
                      {c.label}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {[...DATA].reverse().map((d) => (
                  <tr key={d.week}>
                    <th scope="row">{fmt(d.week)}</th>
                    {CHANNELS.map((c) => (
                      <td key={c.key} className="num">
                        {d.values[c.key]}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </section>
  );
}

export type Channel = { key: string; label: string; series: string };

// Fixed order -> fixed series token; colour follows the channel, never its rank.
export const CHANNELS: Channel[] = [
  { key: 'organic', label: 'Organic search', series: 'var(--series-1)' },
  { key: 'paid', label: 'Paid', series: 'var(--series-2)' },
  { key: 'referral', label: 'Referral', series: 'var(--series-3)' },
];

export type WeekRow = { week: string; values: Record<string, number> };

// 26 weeks ending the week of 2026-11-02. Placeholder data: swap for the real query.
const WEEKS = 26;
const END = Date.UTC(2026, 10, 2);

function build(): WeekRow[] {
  const rows: WeekRow[] = [];
  for (let i = 0; i < WEEKS; i++) {
    const d = new Date(END - (WEEKS - 1 - i) * 7 * 864e5);
    const wobble = (n: number) => Math.round(Math.sin(i * n) * 6);
    rows.push({
      week: d.toISOString().slice(0, 10),
      values: {
        organic: 210 + i * 5 + wobble(1.7),
        paid: 320 - i * 3 + wobble(2.3) + (i % 8 === 0 ? 25 : 0),
        referral: 120 + wobble(0.9) + (i > 17 ? (i - 17) * 7 : 0),
      },
    });
  }
  return rows;
}

export const DATA = build();
